text:
    style.textContent = "/* src/css/base.css */
@layer kui.tokens, kui.presets, kui.effects, kui.policy, kui.cloak;
@layer kui.tokens {
  :root {
    --kui-ease-expo-in: cubic-bezier(0.7, 0, 0.84, 0);
    --kui-ease-expo-out: cubic-bezier(0.16, 1, 0.3, 1);
    --kui-ease-expo-in-out: cubic-bezier(0.87, 0, 0.13, 1);
    --kui-ease-back-in: cubic-bezier(0.36, 0, 0.66, -0.56);
    --kui-ease-back-out: cubic-bezier(0.34, 1.56, 0.64, 1);
    --kui-ease-back-in-out: cubic-bezier(0.68, -0.6, 0.32, 1.6);
    --kui-ease-quart-out: cubic-bezier(0.25, 1, 0.5, 1);
    --kui-ease-circ-out: cubic-bezier(0, 0.55, 0.45, 1);
    --kui-ease-spring: linear(0, 0.4 12%, 0.9 25%, 1.06 38%, 1.01 62%, 1);
    --kui-ease-bounce: linear(0, 0.5 10%, 1.2 30%, 0.9 50%, 1.08 68%, 0.97 82%, 1.02 92%, 1);
  }
  [data-kui-fx] {
    --kui-dir: 1;
    --kui-i: 0;
    --kui-motion-path: initial;
    --kui-motion-rotate: initial;
    --kui-motion-anchor: initial;
    --kui-motion-from: initial;
    --kui-motion-to: initial;
    --kui-wide-sm: initial;
    --kui-narrow-sm: initial;
    --kui-wide-md: initial;
    --kui-narrow-md: initial;
    --kui-wide-lg: initial;
    --kui-narrow-lg: initial;
    --kui-wide-xl: initial;
    --kui-narrow-xl: initial;
    --kui-wide-2xl: initial;
    --kui-narrow-2xl: initial;
  }
  :dir(rtl) [data-kui-fx] {
    --kui-dir: -1;
  }
  :root {
    --kui-above-sm: none;
    --kui-below-sm: initial;
    --kui-above-md: none;
    --kui-below-md: initial;
    --kui-above-lg: none;
    --kui-below-lg: initial;
    --kui-above-xl: none;
    --kui-below-xl: initial;
    --kui-above-2xl: none;
    --kui-below-2xl: initial;
  }
  @media (min-width: 40rem) {
    :root {
      --kui-above-sm: initial;
      --kui-below-sm: none;
    }
  }
  @media (min-width: 48rem) {
    :root {
      --kui-above-md: initial;
      --kui-below-md: none;
    }
  }
  @media (min-width: 64rem) {
    :root {
      --kui-above-lg: initial;
      --kui-below-lg: none;
    }
  }
  @media (min-width: 80rem) {
    :root {
      --kui-above-xl: initial;
      --kui-below-xl: none;
    }
  }
  @media (min-width: 96rem) {
    :root {
      --kui-above-2xl: initial;
      --kui-below-2xl: none;
    }
  }
  @container (min-width: 40rem) {
    [data-kui-fx] {
      --kui-narrow-sm: none;
    }
  }
  @container not (min-width: 40rem) {
    [data-kui-fx] {
      --kui-wide-sm: none;
    }
  }
  @container (min-width: 48rem) {
    [data-kui-fx] {
      --kui-narrow-md: none;
    }
  }
  @container not (min-width: 48rem) {
    [data-kui-fx] {
      --kui-wide-md: none;
    }
  }
  @container (min-width: 64rem) {
    [data-kui-fx] {
      --kui-narrow-lg: none;
    }
  }
  @container not (min-width: 64rem) {
    [data-kui-fx] {
      --kui-wide-lg: none;
    }
  }
  @container (min-width: 80rem) {
    [data-kui-fx] {
      --kui-narrow-xl: none;
    }
  }
  @container not (min-width: 80rem) {
    [data-kui-fx] {
      --kui-wide-xl: none;
    }
  }
  @container (min-width: 96rem) {
    [data-kui-fx] {
      --kui-narrow-2xl: none;
    }
  }
  @container not (min-width: 96rem) {
    [data-kui-fx] {
      --kui-wide-2xl: none;
    }
  }
  [data-kui-container] {
    container-type: inline-size;
  }
}
@layer kui.effects {
  :where([data-kui-fx]) {
    --kui-transition: initial;
    transition: var(--kui-transition);
  }
}
@layer kui.policy {
  html[data-kui-cloak] [data-kui][data-kui-reveal]:not([data-kui-state]) {
    opacity: 0 !important;
  }
  @media (prefers-reduced-motion: reduce) {
    [data-kui-rm],
    [data-kui-rm]::before,
    [data-kui-rm]::after,
    [data-kui-rm] .kui-odometer-strip,
    [data-kui-rm][data-kui-fx~=label-float] ~ label,
    [data-kui-rm][data-kui-fx~=input-underline-grow] ~ .kui-underline,
    [data-kui-rm][data-kui-fx~=toggle-morph] ~ .kui-track,
    [data-kui-rm][data-kui-fx~=toggle-morph] ~ .kui-track .kui-thumb,
    [data-kui-rm][data-kui-fx~=checkbox-draw] ~ svg path,
    [data-kui-rm][data-kui-fx~=radio-fill] ~ .kui-dot,
    [data-kui-rm][data-kui-fx~=strength-meter] ~ .kui-meter > *,
    [data-kui-rm][data-kui-fx~=hamburger-to-x] .kui-bar,
    [data-kui-rm][data-kui-fx~=play-to-pause] .kui-bar,
    [data-kui-rm][data-kui-fx~=plus-to-minus] .kui-bar,
    [data-kui-rm][data-kui-fx~=flip-card] > .kui-face-front,
    [data-kui-rm][data-kui-fx~=flip-card] > .kui-face-back,
    [data-kui-rm][data-kui-fx~=step-progress] > [data-kui-step-state] {
      transition-duration: 1ms !important;
      transition-delay: 0ms !important;
    }
    [data-kui-rm=shorten],
    [data-kui-rm=shorten]::before,
    [data-kui-rm=shorten]::after {
      animation-duration: 1ms !important;
      animation-delay: 0ms !important;
    }
    [data-kui-rm=crossfade] {
      animation-name: kui-in !important;
      animation-duration: 200ms !important;
    }
    [data-kui-rm=disable] {
      animation: none !important;
      opacity: 1 !important;
      translate: none !important;
      scale: none !important;
      rotate: none !important;
      filter: none !important;
      offset-path: none !important;
    }
  }
  @media print {
    [data-kui-fx],
    [data-kui-reveal] {
      animation: none !important;
      opacity: 1 !important;
      translate: none !important;
      scale: none !important;
      rotate: none !important;
      filter: none !important;
      offset-path: none !important;
    }
  }
}

/* src/css/presets.generated.css */
@layer kui.presets {
