/* src/css/entrance.css */
@layer kui.effects {
  @keyframes kui-in {
    from {
      opacity: var(--kui-from-opacity, 0);
    }
  }
  @keyframes kui-out {
    to {
      opacity: 0;
    }
  }
  @keyframes kui-in-up {
    from {
      opacity: var(--kui-from-opacity, 0);
      translate: 0 var(--kui-gate-distance, var(--kui-distance, 24px));
    }
  }
  @keyframes kui-in-down {
    from {
      opacity: var(--kui-from-opacity, 0);
      translate: 0 calc(var(--kui-gate-distance, var(--kui-distance, 24px)) * -1);
    }
  }
  @keyframes kui-in-left {
    from {
      opacity: var(--kui-from-opacity, 0);
      translate: var(--kui-gate-distance, var(--kui-distance, 24px)) 0;
    }
  }
  @keyframes kui-in-right {
    from {
      opacity: var(--kui-from-opacity, 0);
      translate: calc(var(--kui-gate-distance, var(--kui-distance, 24px)) * -1) 0;
    }
  }
  @keyframes kui-out-up {
    to {
      opacity: 0;
      translate: 0 calc(var(--kui-gate-distance, var(--kui-distance, 24px)) * -1);
    }
  }
  @keyframes kui-out-down {
    to {
      opacity: 0;
      translate: 0 var(--kui-gate-distance, var(--kui-distance, 24px));
    }
  }
  @keyframes kui-out-left {
    to {
      opacity: 0;
      translate: calc(var(--kui-gate-distance, var(--kui-distance, 24px)) * -1) 0;
    }
  }
  @keyframes kui-out-right {
    to {
      opacity: 0;
      translate: var(--kui-gate-distance, var(--kui-distance, 24px)) 0;
    }
  }
  @keyframes kui-in-inline-start {
    from {
      opacity: var(--kui-from-opacity, 0);
      translate: calc(var(--kui-gate-distance, var(--kui-distance, 24px)) * var(--kui-dir, 1)) 0;
    }
  }
  @keyframes kui-in-inline-end {
    from {
      opacity: var(--kui-from-opacity, 0);
      translate: calc(var(--kui-gate-distance, var(--kui-distance, 24px)) * var(--kui-dir, 1) * -1) 0;
    }
  }
  @keyframes kui-zoom-in {
    from {
      scale: var(--kui-from-scale, 0.92);
    }
  }
  @keyframes kui-zoom-out {
    to {
      scale: var(--kui-from-scale, 0.92);
    }
  }
  @keyframes kui-zoom-in-up {
    from {
      scale: var(--kui-from-scale, 0.92);
      translate: 0 var(--kui-gate-distance, var(--kui-distance, 24px));
    }
  }
  @keyframes kui-zoom-in-down {
    from {
      scale: var(--kui-from-scale, 0.92);
