  }
  [data-kui-fx~=card-flip-x]:has(> :nth-child(2)),
  [data-kui-fx~=card-flip-y]:has(> :nth-child(2)) {
    display: grid;
  }
  [data-kui-fx~=card-flip-x]:has(> :nth-child(2)) > :first-child,
  [data-kui-fx~=card-flip-x]:has(> :nth-child(2)) > :nth-child(2),
  [data-kui-fx~=card-flip-y]:has(> :nth-child(2)) > :first-child,
  [data-kui-fx~=card-flip-y]:has(> :nth-child(2)) > :nth-child(2) {
    grid-area: 1 / 1;
    backface-visibility: hidden;
  }
