    opacity: 0;
  }
  @keyframes kui-page-fade {
    from {
      opacity: 0;
    }
  }
  @keyframes kui-page-slide {
    from {
      opacity: 0;
      translate: 0 var(--kui-gate-distance, var(--kui-distance, 40px));
    }
  }
  @keyframes kui-curtain-wipe {
