  [data-kui-fx~=flip-card] {
    display: grid;
    perspective: var(--kui-perspective, 1600px);
  }
  [data-kui-fx~=flip-card] > .kui-face-front,
  [data-kui-fx~=flip-card] > .kui-face-back {
