    rotate: y 0deg;
  }
  [data-kui~=flip-card] {
    display: grid;
    perspective: var(--kui-perspective, 1600px);
  }
  [data-kui~=flip-card] > .kui-face-front,
  [data-kui~=flip-card] > .kui-face-back {
    grid-area: 1 / 1;
