/* src/css/carousel.css */
@layer kui.effects {
  [data-kui-fx~=carousel-3d],
  [data-kui-fx~=carousel-3d-high],
  [data-kui-fx~=carousel-3d-low],
  [data-kui-fx~=carousel-3d-inside] {
    display: grid;
    place-items: center;
    perspective: var(--kui-perspective, 1600px);
    transform-style: preserve-3d;
    --kui-ring-tilt: clamp(-80deg, calc(-1 * var(--kui-tilt, 0deg)), 80deg);
    --kui-ring-drift: calc(var(--kui-step-position, 0) - var(--kui-step, 0));
  }
  [data-kui-fx~=carousel-3d] [data-kui-step-offset],
  [data-kui-fx~=carousel-3d-high] [data-kui-step-offset],
  [data-kui-fx~=carousel-3d-low] [data-kui-step-offset],
  [data-kui-fx~=carousel-3d-inside] [data-kui-step-offset] {
    grid-area: 1 / 1;
    backface-visibility: hidden;
    --kui-ring-spacing: calc(var(--kui-arc, 360deg) / max(1, var(--kui-item-count, 1)));
    --kui-ring-angle: calc((var(--kui-offset, 0) - var(--kui-ring-drift)) * var(--kui-ring-spacing));
    --kui-ring-radius: var( --kui-radius, calc( (var(--kui-item-width, 260px) + var(--kui-gap, 24px)) / (2 * tan(clamp(0.5deg, var(--kui-ring-spacing) / 2, 60deg))) ) );
    transform: rotateX(var(--kui-ring-tilt)) rotateY(var(--kui-ring-angle)) translateZ(var(--kui-ring-radius));
    transition: transform var(--kui-spatial-ring-duration, 620ms) var(--kui-spatial-ring-ease, cubic-bezier(0.22, 1, 0.36, 1)) var(--kui-spatial-ring-delay, 0ms);
  }
  [data-kui-ring-dragging=true] [data-kui-step-offset] {
    transition: none;
  }
  [data-kui-ring-face=back] {
    pointer-events: none;
  }
  [data-kui-fx~=carousel-3d-inside] [data-kui-ring-face=back] {
    visibility: hidden;
  }
  [data-kui-fx~=carousel-3d][data-kui-ring-facing=camera] [data-kui-step-offset],
  [data-kui-fx~=carousel-3d-high][data-kui-ring-facing=camera] [data-kui-step-offset],
  [data-kui-fx~=carousel-3d-low][data-kui-ring-facing=camera] [data-kui-step-offset],
  [data-kui-fx~=carousel-3d-inside][data-kui-ring-facing=camera] [data-kui-step-offset] {
    transform-style: preserve-3d;
  }
  [data-kui-fx~=carousel-3d][data-kui-ring-facing=camera] [data-kui-step-offset] > *,
  [data-kui-fx~=carousel-3d-high][data-kui-ring-facing=camera] [data-kui-step-offset] > *,
  [data-kui-fx~=carousel-3d-low][data-kui-ring-facing=camera] [data-kui-step-offset] > *,
  [data-kui-fx~=carousel-3d-inside][data-kui-ring-facing=camera] [data-kui-step-offset] > * {
    transform: rotateY(calc(-1 * var(--kui-ring-angle))) rotateX(calc(-1 * var(--kui-ring-tilt)));
    transform-style: preserve-3d;
  }
  [data-kui-fx~=carousel-3d-inside] [data-kui-step-offset] {
    transform: rotateX(var(--kui-ring-tilt)) rotateY(var(--kui-ring-angle)) translateZ(calc(-1 * var(--kui-ring-radius)));
  }
  [data-kui~=carousel-3d],
  [data-kui~=carousel-3d-high],
  [data-kui~=carousel-3d-low],
  [data-kui~=carousel-3d-inside] {
    display: grid;
    place-items: center;
  }
  [data-kui~=carousel-3d] > *,
  [data-kui~=carousel-3d-high] > *,
  [data-kui~=carousel-3d-low] > *,
