  [data-kui-fx~=compare][data-kui-compare-axis=y] > .kui-compare-range {
    writing-mode: vertical-lr;
    direction: ltr;
    cursor: ns-resize;
    touch-action: pan-x;
  }
  [data-kui-fx~=compare] > .kui-compare-handle {
    grid-area: 1 / 1;
    position: relative;
    z-index: 1;
    inline-size: 100%;
    block-size: 100%;
    pointer-events: none;
    translate: calc(var(--kui-compare, 50%) - 100%) 0;
  }
  [data-kui-fx~=compare][data-kui-compare-axis=y] > .kui-compare-handle {
    translate: 0 calc(var(--kui-compare, 50%) - 100%);
  }
  [data-kui-fx~=compare] > .kui-compare-handle::after {
    content: "";
    position: absolute;
    inset-block: 0;
    inset-inline-end: 0;
    inline-size: 2px;
    background: #fff;
    box-shadow: 0 0 4px rgba(0, 0, 0, 0.5);
    border-inline-start: 2px solid CanvasText;
  }
  [data-kui-fx~=compare][data-kui-compare-axis=y] > .kui-compare-handle::after {
    inset-block: auto 0;
