    border-inline-start: none;
    border-block-start: 2px solid CanvasText;
  }
  [data-kui-fx~=compare] > .kui-compare-handle::before {
    content: "";
    position: absolute;
    inset-block-start: 50%;
    inset-inline-end: -14px;
    translate: 0 -50%;
    inline-size: 28px;
    block-size: 28px;
    border-radius: 50%;
    background: #fff;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.4);
    border: 1px solid rgba(0, 0, 0, 0.15);
  }
  [data-kui-fx~=compare][data-kui-compare-axis=y] > .kui-compare-handle::before {
    inset-block-start: auto;
    inset-block-end: -14px;
    inset-inline-start: 50%;
    inset-inline-end: auto;
    translate: -50% 0;
  }
  [data-kui-fx~=compare] > .kui-compare-range:focus-visible + .kui-compare-handle {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
  [data-kui-fx~=compare] > .kui-compare-range:focus-visible + .kui-compare-handle::before {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
  [data-kui-fx~=hotspots] {
    position: relative;
    display: inline-block;
  }
  [data-kui-fx~=hotspots] > img {
    display: block;
    inline-size: 100%;
    block-size: auto;
  }
  [data-kui-fx~=hotspots] > :is(ol, ul) {
    margin: 0;
    padding: 0;
    block-size: 0;
  }
  [data-kui-fx~=hotspots] .kui-hotspot {
    position: absolute;
    left: var(--kui-x);
    top: var(--kui-y);
    translate: -50% -50%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    padding: 0;
    margin: 0;
    border: 2px solid #fff;
    border-radius: 50%;
    background: var(--kui-hotspot-color, #111);
    color: #fff;
    font-size: 12px;
    font-weight: 600;
    line-height: 1;
    cursor: pointer;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
    touch-action: manipulation;
    user-select: none;
    inline-size: 24px;
    block-size: 24px;
  }
  [data-kui-fx~=hotspots][data-kui-hotspot-marker=dot] .kui-hotspot {
    inline-size: 14px;
    block-size: 14px;
  }
  [data-kui-fx~=hotspots] .kui-hotspot:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
  [data-kui-fx~=hotspots] [popover] {
    margin: 0;
    padding: 8px 12px;
    border-radius: 8px;
    border: 1px solid rgba(255, 255, 255, 0.15);
    background: #1e1e1e;
    color: #fff;
    font-size: 13px;
    line-height: 1.4;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.4);
    max-inline-size: min(18rem, calc(100vw - 16px));
    max-block-size: calc(100vh - 16px);
    overflow: auto;
    overflow-wrap: anywhere;
    transition:
      opacity 150ms ease,
      translate 150ms ease,
      display 150ms allow-discrete,
      overlay 150ms allow-discrete;
    opacity: 0;
    translate: 0 4px;
  }
  [data-kui-fx~=hotspots] [popover]:popover-open {
    opacity: 1;
    translate: 0 0;
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow]) {
    position: relative;
    overflow: hidden;
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow])[data-kui-slideshow-mode=fade] [data-kui-slideshow-list] {
    display: grid;
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow])[data-kui-slideshow-mode=fade] [data-kui-slideshow-list] > [data-kui-step-state] {
    grid-area: 1 / 1;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--kui-slideshow-duration, 500ms) var(--kui-slideshow-ease, ease);
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow])[data-kui-slideshow-mode=fade] [data-kui-slideshow-list] > [data-kui-step-state=active] {
    opacity: 1;
    pointer-events: auto;
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow])[data-kui-slideshow-mode=slide] [data-kui-slideshow-list] {
    display: flex;
    translate: calc(var(--kui-step, 0) * -100%) 0;
    transition: translate var(--kui-slideshow-duration, 500ms) var(--kui-slideshow-ease, ease);
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow])[data-kui-slideshow-mode=slide] [data-kui-slideshow-list] > [data-kui-step-state] {
    flex: 0 0 100%;
    min-inline-size: 0;
  }
  [data-kui-fx~=carousel-fade] [data-kui-slideshow-list] {
    touch-action: pan-y;
  }
  [data-kui-fx~=carousel-slide] [data-kui-slideshow-list] {
    touch-action: pan-y;
  }
  [data-kui-fx~=video-hero-slideshow] [data-kui-slideshow-list] {
    touch-action: pan-y;
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow]) .kui-slideshow-controls {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    padding: 0.75rem;
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow]) .kui-slideshow-controls button {
    display: inline-grid;
    place-items: center;
    min-inline-size: 2.75rem;
