  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow]) .kui-slideshow-controls .kui-slideshow-dot[aria-current=true] {
    background: currentColor;
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow]) .kui-slideshow-controls button:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
  [data-kui-fx~=scroll-story] {
    position: relative;
    box-sizing: border-box;
  }
  [data-kui-fx~=scroll-story] > :first-child {
    position: sticky;
    inset-block-start: 0;
    z-index: 1;
    display: grid;
    block-size: 45svh;
    overflow: hidden;
  }
  [data-kui-fx~=scroll-story] > :first-child [data-kui-step-state] {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
    opacity: 0;
    pointer-events: none;
    transition: opacity 300ms ease;
  }
  [data-kui-fx~=scroll-story] > :first-child [data-kui-step-state=active] {
    opacity: 1;
    pointer-events: auto;
  }
  [data-kui-fx~=scroll-story] > :last-child {
    position: relative;
    z-index: 2;
    margin: 0;
    padding: 0;
    list-style: none;
  }
  [data-kui-fx~=scroll-story] > :last-child [data-kui-step-state] {
    min-block-size: 60vh;
    box-sizing: border-box;
    opacity: var(--kui-story-dim, 0.45);
    transition: opacity 300ms ease;
    background: Canvas;
  }
  [data-kui-fx~=scroll-story] > :last-child [data-kui-step-state=active] {
    opacity: 1;
  }
  @media (min-width: 48rem) {
    [data-kui-fx~=scroll-story] {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: clamp(1.5rem, 3vw, 4rem);
      align-items: start;
    }
    [data-kui-fx~=scroll-story] > :first-child {
      inset-block-start: 0;
      block-size: 100vh;
      block-size: 100svh;
      align-content: center;
    }
    [data-kui-fx~=scroll-story] > :first-child > [data-kui-step-state] {
      position: relative;
      inset: auto;
      grid-area: 1 / 1;
      block-size: auto;
      aspect-ratio: 16 / 10;
    }
    [data-kui-fx~=scroll-story]:not([data-kui-story-side=start]) > :first-child {
      grid-column: 2;
      grid-row: 1;
    }
    [data-kui-fx~=scroll-story]:not([data-kui-story-side=start]) > :last-child {
      grid-column: 1;
      grid-row: 1;
    }
    [data-kui-fx~=scroll-story][data-kui-story-side=start] > :first-child {
      grid-column: 1;
      grid-row: 1;
    }
    [data-kui-fx~=scroll-story][data-kui-story-side=start] > :last-child {
      grid-column: 2;
      grid-row: 1;
    }
    [data-kui-fx~=scroll-story] > :last-child [data-kui-step-state] {
      background: transparent;
    }
  }
  [data-kui-fx~=scroll-story]:not([data-kui-step]) {
    display: block;
  }
  [data-kui-fx~=scroll-story]:not([data-kui-step]) > :first-child {
    position: static;
    display: block;
    block-size: auto;
    overflow: visible;
    aspect-ratio: auto;
  }
  [data-kui-fx~=scroll-story]:not([data-kui-step]) > :first-child * {
    position: static;
    inset: auto;
    grid-area: auto;
    inline-size: auto;
    block-size: auto;
    aspect-ratio: auto;
    opacity: 1;
    pointer-events: auto;
  }
  [data-kui-fx~=scroll-story]:not([data-kui-step]) > :last-child * {
    min-block-size: 0;
    opacity: 1;
  }
  @starting-style {
    [data-kui-fx~=hotspots] [popover]:popover-open {
      opacity: 0;
      translate: 0 4px;
    }
  }
  @media (forced-colors: active) {
    :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow]) .kui-slideshow-controls button {
      border-color: CanvasText;
      color: CanvasText;
    }
    :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow]) .kui-slideshow-controls .kui-slideshow-dot[aria-current=true] {
      background: Highlight;
    }
    [data-kui-device] {
      border-color: CanvasText;
      background: Canvas;
    }
