    }
    [data-kui-fx~=hotspots] [popover] {
      border-color: CanvasText;
      background: Canvas;
      color: CanvasText;
    }
  }
  dialog.kui-lightbox {
    display: none;
  }
  dialog.kui-lightbox[open] {
    position: fixed;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
    max-inline-size: none;
    max-block-size: none;
    box-sizing: border-box;
    margin: 0;
    border: 0;
    padding: clamp(1rem, 4vw, 3rem);
    overflow: auto;
    overscroll-behavior: contain;
    display: grid;
    place-items: center;
    color: #fff;
    background: rgb(8 9 10 / 0.58);
    opacity: 0;
    transition: opacity var(--kui-lightbox-duration, 280ms) var(--kui-lightbox-ease, ease);
  }
  dialog.kui-lightbox::backdrop {
    background: transparent;
    -webkit-backdrop-filter: blur(7px);
    backdrop-filter: blur(7px);
    opacity: 0;
    transition: opacity var(--kui-lightbox-duration, 280ms) var(--kui-lightbox-ease, ease);
  }
  dialog.kui-lightbox[open].is-open {
    opacity: 1;
  }
  dialog.kui-lightbox[open].is-open::backdrop {
    opacity: 1;
  }
  .kui-lightbox-slot {
    display: contents;
