    opacity: 0;
    scale: var(--kui-from-scale, 0.965);
    translate: 0 8px;
    transition:
      opacity var(--kui-lightbox-duration, 280ms) ease,
      scale var(--kui-lightbox-duration, 280ms) var(--kui-lightbox-ease, ease),
      translate var(--kui-lightbox-duration, 280ms) var(--kui-lightbox-ease, ease);
  }
  .kui-lightbox.is-open .kui-lightbox-gallery,
  .kui-lightbox.is-open .kui-lightbox-frame {
    opacity: 1;
    scale: none;
    translate: none;
  }
  .kui-lightbox-gallery {
    display: grid;
    place-items: center;
    gap: 0.75rem;
  }
  .kui-lightbox-gallery figure {
    margin: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.75rem;
  }
  .kui-lightbox-gallery img {
    display: block;
    border-radius: 10px;
    box-shadow: 0 30px 80px rgb(0 0 0 / 0.45);
    background: #0b0c0d;
  }
  .kui-lightbox-gallery img.is-fit {
    max-inline-size: min(100%, 1400px);
    max-block-size: 86dvh;
    inline-size: auto;
    block-size: auto;
  }
  .kui-lightbox-gallery img.is-tall {
    inline-size: min(100%, 760px);
    block-size: auto;
  }
  .kui-lightbox-gallery figcaption {
    max-inline-size: 60ch;
    text-align: center;
    font-size: 0.85rem;
    line-height: 1.5;
    color: rgb(255 255 255 / 0.72);
  }
  .kui-lightbox-close,
  .kui-lightbox-prev,
  .kui-lightbox-next {
    border: 1px solid rgb(255 255 255 / 0.45);
    border-radius: 50%;
    color: #fff;
    background: rgb(8 9 10 / 0.7);
    cursor: pointer;
  }
  .kui-lightbox-close {
    position: fixed;
    inset-block-start: clamp(0.75rem, 2vw, 1.25rem);
    inset-inline-end: clamp(0.75rem, 2vw, 1.25rem);
    z-index: 1;
    inline-size: 40px;
    block-size: 40px;
    font-size: 1.5rem;
  }
  .kui-lightbox-prev,
  .kui-lightbox-next {
    position: fixed;
    inset-block-start: 50%;
    inline-size: 40px;
    block-size: 40px;
    font-size: 2rem;
  }
  .kui-lightbox-prev {
    inset-inline-start: 0.75rem;
  }
  .kui-lightbox-next {
    inset-inline-end: 0.75rem;
  }
  .kui-lightbox-counter {
    font-size: 0.85rem;
    color: rgb(255 255 255 / 0.8);
  }
  .kui-lightbox button:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
  .kui-lightbox-frame {
    inline-size: min(92vw, 1100px);
    aspect-ratio: 16 / 9;
    border-radius: 12px;
    overflow: clip;
    box-shadow: 0 30px 80px rgb(0 0 0 / 0.45);
    background: #000;
  }
  .kui-lightbox-frame--tall {
    inline-size: min(80vw, 420px);
    aspect-ratio: 9 / 16;
  }
  .kui-lightbox-frame--square {
    inline-size: min(80vw, 720px);
    aspect-ratio: 1;
  }
  .kui-lightbox-frame iframe,
  .kui-lightbox-frame video {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    border: 0;
  }
  @media (prefers-reduced-motion: reduce) {
    dialog.kui-lightbox,
    .kui-lightbox-gallery,
    .kui-lightbox-frame {
      transition-duration: 1ms;
    }
    .kui-lightbox-gallery,
    .kui-lightbox-frame {
      scale: none;
      translate: none;
    }
    [data-kui-fx~=scroll-story] > :first-child [data-kui-step-state],
    [data-kui-fx~=scroll-story] > :last-child [data-kui-step-state] {
      transition-duration: 1ms;
    }
  }
  @media (forced-colors: active) {
    dialog.kui-lightbox {
      border: 1px solid CanvasText;
      background: Canvas;
      color: CanvasText;
    }
    dialog.kui-lightbox::backdrop {
      -webkit-backdrop-filter: none;
      backdrop-filter: none;
    }
    .kui-lightbox-close,
    .kui-lightbox-prev,
    .kui-lightbox-next {
      border-color: CanvasText;
      color: CanvasText;
      background: Canvas;
    }
    .kui-lightbox-frame {
      border: 1px solid CanvasText;
    }
    [data-kui-fx~=scroll-story] > :first-child,
    [data-kui-fx~=scroll-story] > :last-child [data-kui-step-state] {
      border: 1px solid CanvasText;
    }
  }
}

/* src/css/index.css */
"

    style.textContent = "/* src/css/base.css */
@layer kui.tokens, kui.presets, kui.effects, kui.policy, kui.cloak;
@layer kui.tokens {
  :root {
    --kui-ease-expo-in: cubic-bezier(0.7, 0, 0.84, 0);
    --kui-ease-expo-out: cubic-bezier(0.16, 1, 0.3, 1);
    --kui-ease-expo-in-out: cubic-bezier(0.87, 0, 0.13, 1);
    --kui-ease-back-in: cubic-bezier(0.36, 0, 0.66, -0.56);
    --kui-ease-back-out: cubic-bezier(0.34, 1.56, 0.64, 1);
    --kui-ease-back-in-out: cubic-bezier(0.68, -0.6, 0.32, 1.6);
    --kui-ease-quart-out: cubic-bezier(0.25, 1, 0.5, 1);
    --kui-ease-circ-out: cubic-bezier(0, 0.55, 0.45, 1);
    --kui-ease-spring: linear(0, 0.4 12%, 0.9 25%, 1.06 38%, 1.01 62%, 1);
    --kui-ease-bounce: linear(0, 0.5 10%, 1.2 30%, 0.9 50%, 1.08 68%, 0.97 82%, 1.02 92%, 1);
  }
  [data-kui-fx] {
    --kui-dir: 1;
    --kui-i: 0;
    --kui-motion-path: initial;
    --kui-motion-rotate: initial;
    --kui-motion-anchor: initial;
    --kui-motion-from: initial;
    --kui-motion-to: initial;
    --kui-wide-sm: initial;
    --kui-narrow-sm: initial;
    --kui-wide-md: initial;
    --kui-narrow-md: initial;
    --kui-wide-lg: initial;
    --kui-narrow-lg: initial;
    --kui-wide-xl: initial;
    --kui-narrow-xl: initial;
    --kui-wide-2xl: initial;
    --kui-narrow-2xl: initial;
  }
  :dir(rtl) [data-kui-fx] {
    --kui-dir: -1;
  }
  :root {
    --kui-above-sm: none;
    --kui-below-sm: initial;
    --kui-above-md: none;
    --kui-below-md: initial;
    --kui-above-lg: none;
    --kui-below-lg: initial;
    --kui-above-xl: none;
    --kui-below-xl: initial;
    --kui-above-2xl: none;
    --kui-below-2xl: initial;
  }
  @media (min-width: 40rem) {
    :root {
      --kui-above-sm: initial;
      --kui-below-sm: none;
    }
  }
  @media (min-width: 48rem) {
    :root {
      --kui-above-md: initial;
      --kui-below-md: none;
    }
  }
  @media (min-width: 64rem) {
    :root {
      --kui-above-lg: initial;
      --kui-below-lg: none;
    }
  }
  @media (min-width: 80rem) {
    :root {
      --kui-above-xl: initial;
      --kui-below-xl: none;
    }
  }
  @media (min-width: 96rem) {
    :root {
      --kui-above-2xl: initial;
      --kui-below-2xl: none;
    }
  }
  @container (min-width: 40rem) {
    [data-kui-fx] {
      --kui-narrow-sm: none;
    }
  }
  @container not (min-width: 40rem) {
    [data-kui-fx] {
      --kui-wide-sm: none;
    }
  }
  @container (min-width: 48rem) {
    [data-kui-fx] {
      --kui-narrow-md: none;
    }
  }
  @container not (min-width: 48rem) {
    [data-kui-fx] {
      --kui-wide-md: none;
    }
  }
  @container (min-width: 64rem) {
    [data-kui-fx] {
      --kui-narrow-lg: none;
    }
  }
  @container not (min-width: 64rem) {
    [data-kui-fx] {
      --kui-wide-lg: none;
    }
  }
  @container (min-width: 80rem) {
    [data-kui-fx] {
      --kui-narrow-xl: none;
    }
  }
  @container not (min-width: 80rem) {
    [data-kui-fx] {
      --kui-wide-xl: none;
    }
  }
  @container (min-width: 96rem) {
    [data-kui-fx] {
      --kui-narrow-2xl: none;
    }
  }
  @container not (min-width: 96rem) {
    [data-kui-fx] {
      --kui-wide-2xl: none;
    }
  }
  [data-kui-container] {
    container-type: inline-size;
  }
}
@layer kui.effects {
  :where([data-kui-fx]) {
    --kui-transition: initial;
    transition: var(--kui-transition);
  }
}
@layer kui.policy {
  html[data-kui-cloak] [data-kui][data-kui-reveal]:not([data-kui-state]) {
    opacity: 0 !important;
  }
  @media (prefers-reduced-motion: reduce) {
    [data-kui-rm],
    [data-kui-rm]::before,
    [data-kui-rm]::after,
    [data-kui-rm] .kui-odometer-strip,
    [data-kui-rm][data-kui-fx~=label-float] ~ label,
    [data-kui-rm][data-kui-fx~=input-underline-grow] ~ .kui-underline,
    [data-kui-rm][data-kui-fx~=toggle-morph] ~ .kui-track,
    [data-kui-rm][data-kui-fx~=toggle-morph] ~ .kui-track .kui-thumb,
    [data-kui-rm][data-kui-fx~=checkbox-draw] ~ svg path,
    [data-kui-rm][data-kui-fx~=radio-fill] ~ .kui-dot,
    [data-kui-rm][data-kui-fx~=strength-meter] ~ .kui-meter > *,
    [data-kui-rm][data-kui-fx~=hamburger-to-x] .kui-bar,
    [data-kui-rm][data-kui-fx~=play-to-pause] .kui-bar,
    [data-kui-rm][data-kui-fx~=plus-to-minus] .kui-bar,
    [data-kui-rm][data-kui-fx~=flip-card] > .kui-face-front,
    [data-kui-rm][data-kui-fx~=flip-card] > .kui-face-back,
    [data-kui-rm][data-kui-fx~=step-progress] > [data-kui-step-state] {
      transition-duration: 1ms !important;
      transition-delay: 0ms !important;
    }
    [data-kui-rm=shorten],
    [data-kui-rm=shorten]::before,
    [data-kui-rm=shorten]::after {
      animation-duration: 1ms !important;
      animation-delay: 0ms !important;
    }
    [data-kui-rm=crossfade] {
      animation-name: kui-in !important;
      animation-duration: 200ms !important;
    }
    [data-kui-rm=disable] {
      animation: none !important;
      opacity: 1 !important;
      translate: none !important;
      scale: none !important;
      rotate: none !important;
      filter: none !important;
      offset-path: none !important;
    }
  }
  @media print {
    [data-kui-fx],
    [data-kui-reveal] {
      animation: none !important;
      opacity: 1 !important;
      translate: none !important;
      scale: none !important;
      rotate: none !important;
      filter: none !important;
      offset-path: none !important;
    }
  }
}

