    pointer-events: none;
  }
  [data-kui-fx~=carousel-3d-inside] [data-kui-ring-face=back] {
    visibility: hidden;
  }
  [data-kui-fx~=carousel-3d][data-kui-ring-facing=camera] [data-kui-step-offset],
  [data-kui-fx~=carousel-3d-high][data-kui-ring-facing=camera] [data-kui-step-offset],
  [data-kui-fx~=carousel-3d-low][data-kui-ring-facing=camera] [data-kui-step-offset],
