      scale var(--kui-anchored-preview-duration, 220ms) var(--kui-anchored-preview-ease, ease-out) var(--kui-anchored-preview-lag, 0ms),
      translate var(--kui-anchored-preview-duration, 220ms) var(--kui-anchored-preview-ease, ease-out) var(--kui-anchored-preview-lag, 0ms);
