/* src/css/discrete.css */
@layer kui.effects {
  [data-kui-fx~=fade-open] {
    transition-behavior: allow-discrete;
    --kui-tx-delay-fade-open: var(--kui-fade-open-delay, 0ms);
    opacity: 1;
  }
  @starting-style {
    [data-kui-fx~=fade-open] {
      opacity: 0;
    }
  }
  [data-kui-fx~=fade-open]:not(:popover-open):not([open]):not([data-open]) {
    opacity: 0;
    display: none;
  }
  [data-kui-fx~=pop-open] {
    transition-behavior: allow-discrete;
    --kui-tx-delay-pop-open: var(--kui-pop-open-delay, 0ms);
    opacity: 1;
    scale: 1;
  }
  @starting-style {
    [data-kui-fx~=pop-open] {
      opacity: 0;
      scale: var(--kui-pop-open-scale, 0.92);
    }
  }
  [data-kui-fx~=pop-open]:not(:popover-open):not([open]):not([data-open]) {
    opacity: 0;
    scale: var(--kui-pop-open-scale, 0.92);
    display: none;
  }
  [data-kui-fx~=scale-open] {
    transition-behavior: allow-discrete;
    --kui-tx-delay-scale-open: var(--kui-scale-open-delay, 0ms);
    scale: 1;
  }
  @starting-style {
    [data-kui-fx~=scale-open] {
      scale: var(--kui-scale-open-scale, 0.85);
    }
  }
  [data-kui-fx~=scale-open]:not(:popover-open):not([open]):not([data-open]) {
    scale: var(--kui-scale-open-scale, 0.85);
    display: none;
  }
  [data-kui-fx~=drop-open] {
    transition-behavior: allow-discrete;
    --kui-tx-delay-drop-open: var(--kui-drop-open-delay, 0ms);
    opacity: 1;
    translate: 0 0;
  }
  @starting-style {
    [data-kui-fx~=drop-open] {
      opacity: 0;
      translate: 0 calc(var(--kui-drop-open-distance, 12px) * -1);
    }
  }
  [data-kui-fx~=drop-open]:not(:popover-open):not([open]):not([data-open]) {
    opacity: 0;
    translate: 0 calc(var(--kui-drop-open-distance, 12px) * -1);
    display: none;
  }
  [data-kui-fx~=slide-open-up] {
    transition-behavior: allow-discrete;
    --kui-tx-delay-slide-open-up: var(--kui-slide-open-up-delay, 0ms);
    opacity: 1;
    translate: 0 0;
  }
  @starting-style {
    [data-kui-fx~=slide-open-up] {
      opacity: 0;
      translate: 0 var(--kui-slide-open-up-distance, 16px);
    }
  }
  [data-kui-fx~=slide-open-up]:not(:popover-open):not([open]):not([data-open]) {
    opacity: 0;
    translate: 0 var(--kui-slide-open-up-distance, 16px);
    display: none;
  }
  [data-kui-fx~=slide-open-down] {
    transition-behavior: allow-discrete;
    --kui-tx-delay-slide-open-down: var(--kui-slide-open-down-delay, 0ms);
    opacity: 1;
    translate: 0 0;
  }
  @starting-style {
    [data-kui-fx~=slide-open-down] {
      opacity: 0;
      translate: 0 calc(var(--kui-slide-open-down-distance, 16px) * -1);
    }
  }
  [data-kui-fx~=slide-open-down]:not(:popover-open):not([open]):not([data-open]) {
    opacity: 0;
    translate: 0 calc(var(--kui-slide-open-down-distance, 16px) * -1);
    display: none;
  }
}

/* src/css/layout.css */
@layer kui.effects {
