/* src/css/svg.css */
@layer kui.effects {
  @keyframes kui-draw-stroke {
    from {
      stroke-dashoffset: var(--kui-path-length, 100);
    }
    to {
      stroke-dashoffset: 0;
    }
  }
  @keyframes kui-draw-signature {
    from {
      stroke-dashoffset: var(--kui-path-length, 100);
    }
    to {
      stroke-dashoffset: 0;
    }
  }
  @keyframes kui-draw-underline {
    from {
      stroke-dashoffset: var(--kui-path-length, 100);
    }
    to {
      stroke-dashoffset: 0;
    }
  }
  @keyframes kui-checkmark-draw {
    from {
      stroke-dashoffset: var(--kui-path-length, 100);
    }
    to {
      stroke-dashoffset: 0;
    }
  }
  @keyframes kui-cross-draw {
    from {
      stroke-dashoffset: var(--kui-path-length, 100);
    }
    to {
      stroke-dashoffset: 0;
    }
  }
