  [data-kui-fx~=draw-signature],
  [data-kui-fx~=draw-underline],
  [data-kui-fx~=checkmark-draw],
  [data-kui-fx~=cross-draw],
  [data-kui-fx~=chart-line-draw] {
    stroke-dasharray: var(--kui-path-length, 100);
    fill: none;
  }
  @keyframes kui-gradient-stroke {
    from {
      stroke: var(--kui-stroke-from, currentColor);
    }
    50% {
      stroke: var(--kui-stroke-via, currentColor);
    }
    to {
      stroke: var(--kui-stroke-to, currentColor);
    }
  }
  [data-kui-fx~=gradient-stroke] {
    --kui-fx-gradient-stroke-iterations: infinite;
  }
  @keyframes kui-heart-fill {
    from {
      clip-path: inset(100% 0 0 0);
    }
    to {
      clip-path: inset(0 0 0 0);
    }
  }
  @keyframes kui-bookmark-fill {
    from {
      clip-path: inset(100% 0 0 0);
    }
    to {
      clip-path: inset(0 0 0 0);
    }
  }
  @keyframes kui-chart-area-fill {
