      animation-timing-function: var(--kui-tween-scale-ease, var(--kui-tween-scale-default-ease, ease-out));
      scale: var(--kui-tween-scale-x, var(--kui-tween-scale, 1)) var(--kui-tween-scale-y, var(--kui-tween-scale, 1));
    }
