    scale: 0;
  }
}
@layer kui.policy {
  @media (prefers-reduced-motion: reduce) {
    [data-kui-rm][data-kui-fx~=hamburger-to-x] [data-kui-part=bar],
    [data-kui-rm][data-kui-fx~=play-to-pause] [data-kui-part=bar],
    [data-kui-rm][data-kui-fx~=plus-to-minus] [data-kui-part=bar] {
