    inset-block-start: clamp(0.75rem, 2vw, 1.25rem);
    inset-inline-end: clamp(0.75rem, 2vw, 1.25rem);
    z-index: 1;
    inline-size: 40px;
    block-size: 40px;
    font-size: 1.5rem;
  }
  .kui-lightbox-prev,
  .kui-lightbox-next {
