    to {
      transform: skewY(var(--kui-to-skew, 0deg));
    }
  }
  @keyframes kui-progress-x {
    from {
      scale: 0 1;
    }
    to {
      scale: 1 1;
    }
  }
  @keyframes kui-progress-y {
    from {
      scale: 1 0;
    }
    to {
      scale: 1 1;
    }
