/* src/css/carousel.css */
@layer kui.effects {
  [data-kui-fx~=carousel-3d],
  [data-kui-fx~=carousel-3d-high],
  [data-kui-fx~=carousel-3d-low],
  [data-kui-fx~=carousel-3d-inside] {
    display: grid;
    place-items: center;
    perspective: var(--kui-perspective, 1600px);
    transform-style: preserve-3d;
    --kui-ring-tilt: clamp(-80deg, calc(-1 * var(--kui-tilt, 0deg)), 80deg);
    --kui-ring-drift: calc(var(--kui-step-position, 0) - var(--kui-step, 0));
  }
