/* src/css/motion-path.css */
@layer kui.effects {
  @keyframes kui-motion-travel {
    from {
      offset-distance: var(--kui-motion-from, 0%);
    }
    to {
      offset-distance: var(--kui-motion-to, 100%);
    }
  }
  [data-kui-fx~=motion-path],
  [data-kui-fx~=path-arc],
  [data-kui-fx~=path-wave],
  [data-kui-fx~=path-loop],
  [data-kui-fx~=path-swoop] {
    offset-path: path(var(--kui-motion-path));
    offset-rotate: var(--kui-motion-rotate, 0deg);
    offset-anchor: var(--kui-motion-anchor, 0 0);
  }
}

/* src/css/view-transitions.css */
@layer kui.effects {
  @supports (view-transition-name: none) {
    :root {
      --kui-vt-duration: 400ms;
      --kui-vt-delay: 0ms;
      --kui-vt-ease: cubic-bezier(0.4, 0, 0.2, 1);
      --kui-vt-distance: 40px;
    }
    :root::view-transition-group(*) {
      animation-duration: var(--kui-vt-duration, 400ms);
      animation-delay: var(--kui-vt-delay, 0ms);
      animation-timing-function: var(--kui-vt-ease, cubic-bezier(0.4, 0, 0.2, 1));
    }
    :root:active-view-transition-type(kui-page-fade)::view-transition-old(root) {
      animation-name: kui-vt-fade-out;
    }
    :root:active-view-transition-type(kui-page-fade)::view-transition-new(root) {
      animation-name: kui-vt-fade-in;
    }
    :root:active-view-transition-type(kui-page-slide)::view-transition-old(root) {
      animation-name: kui-vt-slide-out;
    }
    :root:active-view-transition-type(kui-page-slide)::view-transition-new(root) {
      animation-name: kui-vt-slide-in;
    }
    :root:active-view-transition-type(kui-curtain-wipe)::view-transition-old(root) {
      animation-name: kui-vt-hold;
    }
    :root:active-view-transition-type(kui-curtain-wipe)::view-transition-new(root) {
      animation-name: kui-vt-wipe-in;
      z-index: 1;
    }
    :root::view-transition-old(root),
    :root::view-transition-new(root) {
      animation-duration: var(--kui-vt-duration, 400ms);
      animation-delay: var(--kui-vt-delay, 0ms);
      animation-timing-function: var(--kui-vt-ease, cubic-bezier(0.4, 0, 0.2, 1));
      animation-fill-mode: both;
    }
    @keyframes kui-vt-fade-out {
      to {
        opacity: 0;
      }
    }
    @keyframes kui-vt-fade-in {
      from {
        opacity: 0;
      }
    }
    @keyframes kui-vt-slide-out {
      to {
        opacity: 0;
        translate: 0 calc(-1 * var(--kui-vt-distance, 40px));
      }
    }
    @keyframes kui-vt-slide-in {
      from {
        opacity: 0;
        translate: 0 var(--kui-vt-distance, 40px);
      }
    }
    @keyframes kui-vt-hold {
      from, to {
        opacity: 1;
      }
    }
    @keyframes kui-vt-wipe-in {
      from {
        clip-path: inset(0 0 100% 0);
      }
      to {
        clip-path: inset(0 0 0 0);
      }
    }
    @media (prefers-reduced-motion: reduce) {
      :root::view-transition-group(*),
      :root::view-transition-old(*),
      :root::view-transition-new(*) {
        animation-duration: 1ms !important;
        animation-delay: 0ms !important;
      }
    }
  }
}

/* src/css/glass.css */
@layer kui.effects {
  [data-kui-fx~=glass] {
    backdrop-filter: blur(var(--kui-glass-blur, 16px)) saturate(var(--kui-glass-saturate, 1.6));
    -webkit-backdrop-filter: blur(var(--kui-glass-blur, 16px)) saturate(var(--kui-glass-saturate, 1.6));
    background-color: color-mix(in srgb, var(--kui-glass-tint, #ffffff) calc(var(--kui-glass-opacity, 0.12) * 100%), transparent);
    background-image:
      linear-gradient(
        var(--kui-glass-sheen-angle, 180deg),
        color-mix(in srgb, var(--kui-glass-sheen-color, var(--kui-glass-rim, #ffffff)) calc(var(--kui-glass-sheen, 0.16) * 100%), transparent) 0%,
        transparent 62%);
    border-width: var(--kui-glass-rim-width, 1px);
    border-style: solid;
    border-color: var(--kui-glass-rim, rgb(255 255 255 / 0.22));
    border-radius: var(--kui-glass-radius, 16px);
  }
  @media (forced-colors: active) {
    [data-kui-fx~=glass] {
      backdrop-filter: none;
      -webkit-backdrop-filter: none;
      background-image: none;
    }
  }
}

/* src/css/ready-gates.css */
@layer kui.effects {
  @property --kui-gate-distance { syntax: "*"; inherits: false; }
  @property --kui-gate-from-angle { syntax: "*"; inherits: false; }
  @property --kui-gate-bar-from { syntax: "*"; inherits: false; }
  [data-kui-fx][data-kui-state=ready] {
    --kui-gate-distance: 0px;
  }
  [data-kui-fx~=flip-in-x][data-kui-state=ready],
  [data-kui-fx~=flip-in-y][data-kui-state=ready],
  [data-kui-fx~=rotate-in][data-kui-state=ready],
  [data-kui-fx~=rotate-in-left][data-kui-state=ready],
  [data-kui-fx~=rotate-in-right][data-kui-state=ready],
  [data-kui-fx~=swing-in][data-kui-state=ready],
  [data-kui-fx~=roll-in][data-kui-state=ready],
  [data-kui-fx~=fold-panel][data-kui-state=ready] {
    --kui-gate-from-angle: 0deg;
  }
  [data-kui-fx~=loading-bar][data-kui-state=ready],
  [data-kui-fx~=chart-bar-grow][data-kui-state=ready],
  [data-kui-fx~=progress-bar][data-kui-state=ready] {
    --kui-gate-bar-from: 1;
  }
}

/* src/css/flip-card-parts.css */
@layer kui.effects {
  [data-kui-fx~=flip-card] > :is(.kui-face-front, [data-kui-part=front]),
  [data-kui-fx~=flip-card] > :is(.kui-face-back, [data-kui-part=back]) {
    grid-area: 1 / 1;
    backface-visibility: hidden;
    transition: rotate var(--kui-card-toggle-duration, 700ms) var(--kui-card-toggle-ease, ease-in-out);
  }
  [data-kui-fx~=flip-card] > :is(.kui-face-front, [data-kui-part=front]) {
    rotate: y 0deg;
  }
  [data-kui-fx~=flip-card] > :is(.kui-face-back, [data-kui-part=back]) {
    rotate: y 180deg;
  }
  [data-kui-fx~=flip-card]:has(> :is(.kui-flip-control, [data-kui-part~=control])[aria-pressed=true]) > :is(.kui-face-front, [data-kui-part=front]),
  [data-kui-fx~=flip-card]:has(> :is(.kui-flip-control, [data-kui-part~=control])[aria-pressed=true]) > :is(.kui-face-back, [data-kui-part=back]) {
    transition-delay: var(--kui-card-toggle-delay, 0ms);
  }
  [data-kui-fx~=flip-card]:has(> :is(.kui-flip-control, [data-kui-part~=control])[aria-pressed=true]) > :is(.kui-face-front, [data-kui-part=front]) {
    rotate: y -180deg;
  }
  [data-kui-fx~=flip-card]:has(> :is(.kui-flip-control, [data-kui-part~=control])[aria-pressed=true]) > :is(.kui-face-back, [data-kui-part=back]) {
    rotate: y 0deg;
  }
  [data-kui-fx~=flip-card] > [data-kui-part~=control][data-kui-part~=injected] {
    grid-area: 1 / 1;
    align-self: end;
    justify-self: end;
    z-index: 1;
    margin: .75rem;
  }
  [data-kui-fx~=flip-card] > [data-kui-part~=quiet]:not(:focus-visible) {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }
  :is([data-kui~=flip-card], [data-kui~="flip-card,"]):not(:has(> .kui-face-front)) > :nth-child(1 of :not(button)) {
    grid-area: 1 / 1;
    backface-visibility: hidden;
    rotate: y 0deg;
  }
  :is([data-kui~=flip-card], [data-kui~="flip-card,"]):not(:has(> .kui-face-front)) > :nth-child(2 of :not(button)) {
    grid-area: 1 / 1;
    backface-visibility: hidden;
    rotate: y 180deg;
  }
}
@layer kui.policy {
  @media (prefers-reduced-motion: reduce) {
    [data-kui-rm][data-kui-fx~=flip-card] > [data-kui-part=front],
    [data-kui-rm][data-kui-fx~=flip-card] > [data-kui-part=back] {
      transition-duration: 1ms !important;
      transition-delay: 0ms !important;
    }
  }
}

/* src/css/icon-parts.css */
@layer kui.effects {
  [data-kui-fx~=hamburger-to-x] [data-kui-part=bar] {
    transition:
      translate var(--kui-icon-toggle-duration, 260ms) var(--kui-icon-toggle-ease, ease-out),
      rotate var(--kui-icon-toggle-duration, 260ms) var(--kui-icon-toggle-ease, ease-out),
      opacity var(--kui-icon-toggle-duration, 260ms) var(--kui-icon-toggle-ease, ease-out);
  }
  [data-kui-fx~=hamburger-to-x][aria-expanded=true] [data-kui-part=bar] {
    transition-delay: var(--kui-icon-toggle-delay, 0ms);
  }
  [data-kui-fx~=hamburger-to-x][aria-expanded=true] [data-kui-part=bar]:nth-child(1 of [data-kui-part=bar]) {
    translate: 0 var(--kui-bar-gap, 6px);
    rotate: 45deg;
  }
  [data-kui-fx~=hamburger-to-x][aria-expanded=true] [data-kui-part=bar]:nth-child(2 of [data-kui-part=bar]) {
    opacity: 0;
  }
  [data-kui-fx~=hamburger-to-x][aria-expanded=true] [data-kui-part=bar]:nth-child(3 of [data-kui-part=bar]) {
    translate: 0 calc(var(--kui-bar-gap, 6px) * -1);
    rotate: -45deg;
  }
  [data-kui-fx~=play-to-pause] [data-kui-part=bar] {
    transition: translate var(--kui-icon-toggle-duration, 260ms) var(--kui-icon-toggle-ease, ease-out), clip-path var(--kui-icon-toggle-duration, 260ms) var(--kui-icon-toggle-ease, ease-out);
  }
  [data-kui-fx~=play-to-pause]:not([aria-pressed=true]) [data-kui-part=bar] {
    transition-delay: var(--kui-icon-toggle-delay, 0ms);
  }
  [data-kui-fx~=play-to-pause]:not([aria-pressed=true]) [data-kui-part=bar]:nth-child(1 of [data-kui-part=bar]) {
    translate: var(--kui-bar-gap, 4px) 0;
    clip-path: polygon(0 0, 100% 25%, 100% 75%, 0 100%);
  }
  [data-kui-fx~=play-to-pause]:not([aria-pressed=true]) [data-kui-part=bar]:nth-child(2 of [data-kui-part=bar]) {
    translate: calc(var(--kui-bar-gap, 4px) * -1) 0;
    clip-path: polygon(0 25%, 100% 50%, 100% 50%, 0 75%);
  }
  [data-kui-fx~=plus-to-minus] [data-kui-part=bar] {
    transition: scale var(--kui-icon-toggle-duration, 260ms) var(--kui-icon-toggle-ease, ease-out);
  }
  [data-kui-fx~=plus-to-minus] [data-kui-part=bar]:nth-child(2 of [data-kui-part=bar]) {
    rotate: 90deg;
  }
  [data-kui-fx~=plus-to-minus][aria-expanded=true] [data-kui-part=bar] {
    transition-delay: var(--kui-icon-toggle-delay, 0ms);
  }
  [data-kui-fx~=plus-to-minus][aria-expanded=true] [data-kui-part=bar]:nth-child(1 of [data-kui-part=bar]) {
    scale: 0;
  }
}
@layer kui.policy {
  @media (prefers-reduced-motion: reduce) {
    [data-kui-rm][data-kui-fx~=hamburger-to-x] [data-kui-part=bar],
    [data-kui-rm][data-kui-fx~=play-to-pause] [data-kui-part=bar],
    [data-kui-rm][data-kui-fx~=plus-to-minus] [data-kui-part=bar] {
      transition-duration: 1ms !important;
      transition-delay: 0ms !important;
    }
  }
}

/* src/showcase/presets.generated.css */
@layer kui.presets {
  [data-kui-fx~=carousel-fade] {
    --kui-slideshow-transition: fade;
    --kui-slideshow-duration: 500ms;
    --kui-slideshow-ease: ease;
  }
  [data-kui-fx~=carousel-slide] {
    --kui-slideshow-transition: slide;
    --kui-slideshow-duration: 500ms;
    --kui-slideshow-ease: ease;
  }
  [data-kui-fx~=lightbox] {
    --kui-lightbox-media: image;
    --kui-lightbox-duration: 280ms;
    --kui-lightbox-ease: cubic-bezier(0.22, 1, 0.36, 1);
  }
  [data-kui-fx~=video-hero-slideshow] {
    --kui-slideshow-transition: fade;
    --kui-slideshow-autoplay: 7s;
    --kui-slideshow-controls: dots;
    --kui-slideshow-duration: 500ms;
    --kui-slideshow-ease: ease;
  }
  [data-kui-fx~=video-lightbox] {
    --kui-lightbox-media: video;
    --kui-lightbox-duration: 280ms;
    --kui-lightbox-ease: cubic-bezier(0.22, 1, 0.36, 1);
  }
}
@layer kui.cloak {
}

/* src/showcase/showcase.css */
@layer kui.effects {
  .kui-slowmo-toggle {
    display: inline-block;
    margin-block-end: 0.75rem;
    padding: 0.4em 0.8em;
    border: 1px solid currentColor;
    border-radius: 0.4em;
    background: Canvas;
    color: CanvasText;
    font: inherit;
    cursor: pointer;
  }
  .kui-slowmo-toggle:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
  [data-kui-device] {
    position: relative;
    display: inline-block;
    box-sizing: border-box;
    overflow: hidden;
    border: 1px solid color-mix(in srgb, var(--kui-device-color, #111) 55%, transparent);
    border-radius: var(--kui-device-radius, 18px);
    padding: 14px;
    background: var(--kui-device-color, #111);
  }
  [data-kui-device] > img,
  [data-kui-device] > video {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }
  [data-kui-device=browser] {
    padding: 30px 14px 14px;
    border-radius: var(--kui-device-radius, 10px);
  }
  [data-kui-device=browser]::before {
    content: "";
    position: absolute;
    inset-block-start: 10px;
    inset-inline-start: 15px;
    inline-size: 44px;
    block-size: 10px;
    background-image:
      radial-gradient(
        circle,
        #ff5f57 0 45%,
        transparent 46%),
      radial-gradient(
        circle,
        #febc2e 0 45%,
        transparent 46%),
      radial-gradient(
        circle,
        #28c840 0 45%,
        transparent 46%);
    background-size: 10px 10px;
    background-position:
      0 0,
      17px 0,
      34px 0;
    background-repeat: no-repeat;
  }
  [data-kui-device=phone] {
    padding: 16px 8px;
    border-radius: var(--kui-device-radius, 36px);
    aspect-ratio: 9 / 19.5;
    max-inline-size: 20rem;
    margin-inline: auto;
  }
  [data-kui-device=phone]::after {
    content: "";
    position: absolute;
    inset-block-start: 0;
    inset-inline-start: 50%;
    translate: -50% 0;
    inline-size: 38%;
    block-size: 16px;
    background-image: radial-gradient(circle, #000 0 100%);
    background-size: 100% 100%;
    border-radius: 0 0 12px 12px;
  }
  [data-kui-device=tablet] {
    padding: 18px;
    border-radius: var(--kui-device-radius, 22px);
    aspect-ratio: 3 / 4;
    max-inline-size: 28rem;
    margin-inline: auto;
  }
  [data-kui-device=laptop] {
    padding: 10px 10px 34px;
    border-radius: var(--kui-device-radius, 12px) var(--kui-device-radius, 12px) 4px 4px;
    aspect-ratio: 16 / 10;
  }
  [data-kui-device=laptop]::after {
    content: "";
    position: absolute;
    inset-block-end: 14px;
    inset-inline-start: 50%;
    translate: -50% 0;
    inline-size: 15%;
    block-size: 6px;
    background-image: radial-gradient(circle, color-mix(in srgb, var(--kui-device-color, #111) 55%, #fff) 0 100%);
    background-size: 100% 100%;
    border-radius: 3px;
  }
  [data-kui-fx~=compare] {
    position: relative;
    display: grid;
    grid-template-columns: 1fr;
    grid-template-rows: 1fr auto;
    overflow: hidden;
    user-select: none;
  }
  [data-kui-fx~=compare] > :is(img, picture, video) {
    grid-area: 1 / 1;
    display: block;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }
  [data-kui-fx~=compare] > :is(img, picture, video):nth-child(2 of :is(img, picture, video)) {
    clip-path: inset(0 0 0 var(--kui-compare, 50%));
  }
  [data-kui-fx~=compare][data-kui-compare-axis=y] > :is(img, picture, video):nth-child(2 of :is(img, picture, video)) {
    clip-path: inset(var(--kui-compare, 50%) 0 0 0);
  }
  [data-kui-fx~=compare] > .kui-compare-range {
    grid-area: 1 / 1;
    position: relative;
    z-index: 2;
    inline-size: 100%;
    block-size: 100%;
    margin: 0;
    padding: 0;
    opacity: 0;
    cursor: ew-resize;
    touch-action: pan-y;
  }
  [data-kui-fx~=compare][data-kui-compare-axis=y] > .kui-compare-range {
    writing-mode: vertical-lr;
    direction: ltr;
    cursor: ns-resize;
    touch-action: pan-x;
  }
  [data-kui-fx~=compare] > .kui-compare-handle {
    grid-area: 1 / 1;
    position: relative;
    z-index: 1;
    inline-size: 100%;
    block-size: 100%;
    pointer-events: none;
    translate: calc(var(--kui-compare, 50%) - 100%) 0;
  }
  [data-kui-fx~=compare][data-kui-compare-axis=y] > .kui-compare-handle {
    translate: 0 calc(var(--kui-compare, 50%) - 100%);
  }
  [data-kui-fx~=compare] > .kui-compare-handle::after {
    content: "";
    position: absolute;
    inset-block: 0;
    inset-inline-end: 0;
    inline-size: 2px;
    background: #fff;
    box-shadow: 0 0 4px rgba(0, 0, 0, 0.5);
    border-inline-start: 2px solid CanvasText;
  }
  [data-kui-fx~=compare][data-kui-compare-axis=y] > .kui-compare-handle::after {
    inset-block: auto 0;
    inset-inline: 0;
    inline-size: 100%;
    block-size: 2px;
    border-inline-start: none;
    border-block-start: 2px solid CanvasText;
  }
  [data-kui-fx~=compare] > .kui-compare-handle::before {
    content: "";
    position: absolute;
    inset-block-start: 50%;
    inset-inline-end: -14px;
    translate: 0 -50%;
    inline-size: 28px;
    block-size: 28px;
    border-radius: 50%;
    background: #fff;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.4);
    border: 1px solid rgba(0, 0, 0, 0.15);
  }
  [data-kui-fx~=compare][data-kui-compare-axis=y] > .kui-compare-handle::before {
    inset-block-start: auto;
    inset-block-end: -14px;
    inset-inline-start: 50%;
    inset-inline-end: auto;
    translate: -50% 0;
  }
  [data-kui-fx~=compare] > .kui-compare-range:focus-visible + .kui-compare-handle {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
  [data-kui-fx~=compare] > .kui-compare-range:focus-visible + .kui-compare-handle::before {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
  [data-kui-fx~=hotspots] {
    position: relative;
    display: inline-block;
  }
  [data-kui-fx~=hotspots] > img {
    display: block;
    inline-size: 100%;
    block-size: auto;
  }
  [data-kui-fx~=hotspots] > :is(ol, ul) {
    margin: 0;
    padding: 0;
    block-size: 0;
  }
  [data-kui-fx~=hotspots] .kui-hotspot {
    position: absolute;
    left: var(--kui-x);
    top: var(--kui-y);
    translate: -50% -50%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    padding: 0;
    margin: 0;
    border: 2px solid #fff;
    border-radius: 50%;
    background: var(--kui-hotspot-color, #111);
    color: #fff;
    font-size: 12px;
    font-weight: 600;
    line-height: 1;
    cursor: pointer;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
    touch-action: manipulation;
    user-select: none;
    inline-size: 24px;
    block-size: 24px;
  }
  [data-kui-fx~=hotspots][data-kui-hotspot-marker=dot] .kui-hotspot {
    inline-size: 14px;
    block-size: 14px;
  }
  [data-kui-fx~=hotspots] .kui-hotspot:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
  [data-kui-fx~=hotspots] [popover] {
    margin: 0;
    padding: 8px 12px;
    border-radius: 8px;
    border: 1px solid rgba(255, 255, 255, 0.15);
    background: #1e1e1e;
    color: #fff;
    font-size: 13px;
    line-height: 1.4;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.4);
    max-inline-size: min(18rem, calc(100vw - 16px));
    max-block-size: calc(100vh - 16px);
    overflow: auto;
    overflow-wrap: anywhere;
    transition:
      opacity 150ms ease,
      translate 150ms ease,
      display 150ms allow-discrete,
      overlay 150ms allow-discrete;
    opacity: 0;
    translate: 0 4px;
  }
  [data-kui-fx~=hotspots] [popover]:popover-open {
    opacity: 1;
    translate: 0 0;
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow]) {
    position: relative;
    overflow: hidden;
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow])[data-kui-slideshow-mode=fade] [data-kui-slideshow-list] {
    display: grid;
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow])[data-kui-slideshow-mode=fade] [data-kui-slideshow-list] > [data-kui-step-state] {
    grid-area: 1 / 1;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--kui-slideshow-duration, 500ms) var(--kui-slideshow-ease, ease);
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow])[data-kui-slideshow-mode=fade] [data-kui-slideshow-list] > [data-kui-step-state=active] {
    opacity: 1;
    pointer-events: auto;
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow])[data-kui-slideshow-mode=slide] [data-kui-slideshow-list] {
    display: flex;
    translate: calc(var(--kui-step, 0) * -100%) 0;
    transition: translate var(--kui-slideshow-duration, 500ms) var(--kui-slideshow-ease, ease);
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow])[data-kui-slideshow-mode=slide] [data-kui-slideshow-list] > [data-kui-step-state] {
    flex: 0 0 100%;
    min-inline-size: 0;
  }
  [data-kui-fx~=carousel-fade] [data-kui-slideshow-list] {
    touch-action: pan-y;
  }
  [data-kui-fx~=carousel-slide] [data-kui-slideshow-list] {
    touch-action: pan-y;
  }
  [data-kui-fx~=video-hero-slideshow] [data-kui-slideshow-list] {
    touch-action: pan-y;
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow]) .kui-slideshow-controls {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    padding: 0.75rem;
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow]) .kui-slideshow-controls button {
    display: inline-grid;
    place-items: center;
    min-inline-size: 2.75rem;
    min-block-size: 2.75rem;
    border: 1px solid currentColor;
    border-radius: 999px;
    background: Canvas;
    color: CanvasText;
    cursor: pointer;
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow]) .kui-slideshow-controls button[aria-label="Previous slide"]::before {
    content: "\2190";
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow]) .kui-slideshow-controls button[aria-label="Next slide"]::before {
    content: "\2192";
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow]) .kui-slideshow-controls button[aria-label="Pause slideshow"]::before {
    content: "\2161";
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow]) .kui-slideshow-controls button[aria-label="Play slideshow"]::before {
    content: "\25b6";
  }
  :is([data-kui-fx~=carousel-fade], [data-kui-fx~=carousel-slide], [data-kui-fx~=video-hero-slideshow]) .kui-slideshow-controls .kui-slideshow-dot {
