  [data-kui-fx~=heart-fill][data-kui-state=ready],
  [data-kui-fx~=bookmark-fill][data-kui-state=ready],
  [data-kui-fx~=chart-area-fill][data-kui-state=ready] {
    clip-path: none !important;
    opacity: 0;
  }
  @keyframes kui-chart-bar-grow {
    from {
      scale: 1 var(--kui-gate-bar-from, var(--kui-bar-from, 0));
    }
    to {
      scale: 1 1;
    }
  }
  [data-kui-fx~=chart-bar-grow] {
    transform-origin: bottom center;
  }
  [data-kui-fx~=chart-bar-grow][data-kui-state=ready] {
    opacity: 0;
  }
  @keyframes kui-logo-build {
    from {
      opacity: 0;
      scale: 0.62;
      rotate: -8deg;
    }
    to {
      opacity: 1;
      scale: 1;
      rotate: 0deg;
    }
  }
  [data-kui-fx~=hamburger-to-x] .kui-bar {
    transition:
      translate var(--kui-icon-toggle-duration, 260ms) var(--kui-icon-toggle-ease, ease-out),
      rotate var(--kui-icon-toggle-duration, 260ms) var(--kui-icon-toggle-ease, ease-out),
      opacity var(--kui-icon-toggle-duration, 260ms) var(--kui-icon-toggle-ease, ease-out);
  }
  [data-kui-fx~=hamburger-to-x][aria-expanded=true] .kui-bar {
    transition-delay: var(--kui-icon-toggle-delay, 0ms);
  }
  [data-kui-fx~=hamburger-to-x][aria-expanded=true] .kui-bar:nth-child(1) {
    translate: 0 var(--kui-bar-gap, 6px);
    rotate: 45deg;
  }
  [data-kui-fx~=hamburger-to-x][aria-expanded=true] .kui-bar:nth-child(2) {
    opacity: 0;
  }
  [data-kui-fx~=hamburger-to-x][aria-expanded=true] .kui-bar:nth-child(3) {
    translate: 0 calc(var(--kui-bar-gap, 6px) * -1);
    rotate: -45deg;
  }
  [data-kui-fx~=play-to-pause] .kui-bar {
    transition: translate var(--kui-icon-toggle-duration, 260ms) var(--kui-icon-toggle-ease, ease-out), clip-path var(--kui-icon-toggle-duration, 260ms) var(--kui-icon-toggle-ease, ease-out);
  }
  [data-kui-fx~=play-to-pause]:not([aria-pressed=true]) .kui-bar {
    transition-delay: var(--kui-icon-toggle-delay, 0ms);
  }
  [data-kui-fx~=play-to-pause]:not([aria-pressed=true]) .kui-bar:nth-child(1) {
    translate: var(--kui-bar-gap, 4px) 0;
    clip-path: polygon(0 0, 100% 25%, 100% 75%, 0 100%);
  }
  [data-kui-fx~=play-to-pause]:not([aria-pressed=true]) .kui-bar:nth-child(2) {
    translate: calc(var(--kui-bar-gap, 4px) * -1) 0;
    clip-path: polygon(0 25%, 100% 50%, 100% 50%, 0 75%);
  }
  [data-kui-fx~=plus-to-minus] .kui-bar {
    transition: scale var(--kui-icon-toggle-duration, 260ms) var(--kui-icon-toggle-ease, ease-out);
  }
  [data-kui-fx~=plus-to-minus] .kui-bar:nth-child(2) {
    rotate: 90deg;
  }
  [data-kui-fx~=plus-to-minus][aria-expanded=true] {
    rotate: 90deg;
    --kui-tx-delay-plus-to-minus: var(--kui-icon-toggle-delay, 0ms);
  }
  [data-kui-fx~=plus-to-minus][aria-expanded=true] .kui-bar {
    transition-delay: var(--kui-icon-toggle-delay, 0ms);
  }
  [data-kui-fx~=plus-to-minus][aria-expanded=true] .kui-bar:nth-child(1) {
    scale: 0;
  }
}

